// Valida el registro, recalcula el puntaje en el servidor y arma el correo.
// [CONFIGURAR] Número de WhatsApp de Martha (código de país + número, solo dígitos). Ej: 573001234567
const MARTHA_WA = '';
const LOGO_URL = 'https://prospeccion.networkerconia.tech/assets/img/logo-correo.png';

const body = $input.first().json.body || {};
const clean = (v, max = 200) => String(v ?? '').replace(/[\u0000-\u001f]/g, ' ').trim().slice(0, max);
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const id = clean(body.id, 40);
const nombre = clean(body.nombre, 80);
const email = clean(body.email, 120).toLowerCase();
const autoriza = body.whatsapp_autoriza === true;
const whatsapp = autoriza ? clean(body.whatsapp, 20).replace(/[^\d+]/g, '') : '';

const POINTS = { p1: {A:1,B:2,C:3}, p2: {A:1,B:3,C:2}, p3: {A:1,B:2,C:3}, p4: {A:1,B:2,C:3}, p5: {A:0,B:0,C:0} };
const TEXTS = {
  p1: {A:'Sí, estoy logrando buenos resultados.', B:'Gano, pero esperaba mucho más.', C:'No consigo los ingresos que deseo.'},
  p2: {A:'No, puedo cobrar sin depender de rangos.', B:'Sí, necesito alcanzar determinados rangos.', C:'No conozco bien las condiciones de mi plan.'},
  p3: {A:'Sí, sé cómo hacerlo.', B:'Conozco algunas técnicas, pero me falta práctica.', C:'No, normalmente solo explico y espero su respuesta.'},
  p4: {A:'Sí, tengo un sistema que puedo duplicar.', B:'Tengo algunas estrategias, pero no soy constante.', C:'No, todavía no tengo un sistema definido.'},
  p5: {A:'Un plan de compensación con mejores posibilidades de crecimiento.', B:'Formación, herramientas digitales y acompañamiento.', C:'Una empresa que reúna todo lo anterior.'}
};

const errors = [];
if (!/^[a-f0-9]{8,40}$/i.test(id)) errors.push('id');
if (nombre.length < 2) errors.push('nombre');
if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(email)) errors.push('email');
if (autoriza && !/^\+\d{9,15}$/.test(whatsapp)) errors.push('whatsapp');

const answers = {};
let puntaje = 0;
for (const k of ['p1','p2','p3','p4','p5']) {
  const letra = clean(body[k] && body[k].letra, 1).toUpperCase();
  if (!(letra in POINTS[k])) { errors.push(k); continue; }
  answers[k] = `${letra} — ${TEXTS[k][letra]}`;
  puntaje += POINTS[k][letra];   // p5 suma 0: solo segmenta
}

if (errors.length) return [{ json: { valid: false, errors } }];

const RESULTS = [
  { min: 4, max: 5, title: '¡Felicidades! Tu multinivel te impulsa.', paras: [
    'La empresa que elegiste te está ofreciendo condiciones que favorecen tu crecimiento. ¡Eso es una buena noticia!',
    'Pero quiero hacerte una pregunta: ¿te has puesto a pensar que podrían existir otras empresas de mercadeo en red que te ofrezcan todavía más posibilidades para crecer y alcanzar tus metas?'] },
  { min: 6, max: 8, title: 'Tienes oportunidades de crecimiento.', paras: [
    'La empresa que elegiste tiene aspectos que pueden ayudarte a avanzar, pero también hay oportunidades que quizá todavía no estás aprovechando.',
    'Ahora bien, ¿te has preguntado si existen otras empresas de mercadeo en red que podrían ofrecerte mejores condiciones para crecer y desarrollar tu negocio?'] },
  { min: 9, max: 10, title: 'Tu multinivel podría estar limitándote.', paras: [
    'Tus respuestas muestran que hay aspectos de tu negocio que podrían estar frenando tus resultados.',
    'Quizá no se trata de trabajar más, sino de contar con un plan de compensación y un sistema de trabajo que te permitan avanzar con mayores posibilidades.',
    '¿Te has dado la oportunidad de conocer otras empresas antes de seguir invirtiendo tu tiempo y esfuerzo?'] },
  { min: 11, max: 12, title: 'Es momento de evaluar nuevas oportunidades.', paras: [
    'Tus respuestas muestran que hay varios aspectos de tu negocio que no están funcionando como esperas.',
    'Tal vez sea momento de preguntarte si la empresa que elegiste actualmente es la mejor opción para alcanzar tus objetivos o si existe otra oportunidad de mercadeo en red que se ajuste mejor a lo que estás buscando.'] }
];
const res = RESULTS.find(r => puntaje >= r.min && puntaje <= r.max) || RESULTS[3];

const waText = `Hola Martha, soy ${nombre}. Hice el test «¿Tu multinivel te impulsa o te limita?» y mi resultado fue: «${res.title.replace(/\.$/, '')}». Quiero conocer esta oportunidad.`;
const waUrl = `https://wa.me/${MARTHA_WA}?text=${encodeURIComponent(waText)}`;

const desc = res.paras.map(p => `<p style="margin:0 0 10px;">${esc(p)}</p>`).join('');
const html = `<!DOCTYPE html><html lang="es"><body style="margin:0;padding:0;background:#FFF9F2;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FFF9F2;"><tr><td align="center" style="padding:28px 12px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#FFFFFF;border-radius:18px;border:1px solid #eee3d3;overflow:hidden;font-family:Arial,Helvetica,sans-serif;color:#142D4E;">
<tr><td style="height:5px;background:#16A6A1;font-size:0;line-height:0;">&nbsp;</td></tr>
<tr><td align="center" style="padding:28px 28px 8px;"><img src="${LOGO_URL}" width="96" height="96" alt="Martha Lucía Hoyos" style="display:block;border-radius:50%;border:3px solid #D4AD63;"></td></tr>
<tr><td style="padding:12px 32px 0;font-size:16px;line-height:1.6;">
<p style="margin:0 0 12px;">Hola, <strong>${esc(nombre)}</strong>.</p>
<p style="margin:0 0 18px;">¡Gracias por realizar nuestro test!</p>
<p style="margin:0 0 10px;color:#4d5f78;">De acuerdo con tus respuestas, este es el resultado de tu evaluación:</p></td></tr>
<tr><td style="padding:6px 32px 4px;"><div style="background:#eefaf9;border-left:5px solid #16A6A1;border-radius:12px;padding:18px 20px;">
<p style="margin:0 0 10px;font-size:21px;font-weight:bold;color:#142D4E;line-height:1.3;">${esc(res.title)}</p>
<div style="font-size:15.5px;line-height:1.6;color:#3f5270;">${desc}</div></div></td></tr>
<tr><td style="padding:18px 32px 0;font-size:16px;line-height:1.6;">
<p style="margin:0 0 12px;">Quiero invitarte a reflexionar sobre algo:</p>
<p style="margin:0 0 12px;background:#fdf3e6;border-radius:12px;padding:14px 16px;color:#142D4E;">¿Y si existiera una empresa de mercadeo en red que te ofreciera mejores posibilidades para desarrollar tu negocio, generar ingresos residuales y brindar mayor bienestar a tu familia?</p>
<p style="margin:0 0 12px;">Yo elegí una empresa para desarrollar mi negocio y quiero darte la oportunidad de conocerla.</p>
<p style="margin:0 0 18px;">Si deseas conversar conmigo y conocer esta oportunidad, puedes hacerlo a través de WhatsApp:</p></td></tr>
<tr><td align="center" style="padding:0 32px 26px;"><a href="${waUrl}" style="display:inline-block;background:#16A6A1;color:#FFFFFF;text-decoration:none;font-weight:bold;font-size:16px;letter-spacing:.03em;padding:15px 30px;border-radius:999px;border:2px solid #ead3a0;">QUIERO CONOCER ESTA OPORTUNIDAD</a></td></tr>
<tr><td style="padding:0 32px 30px;font-size:16px;line-height:1.5;border-top:1px solid #f0e6d6;">
<p style="margin:22px 0 4px;">Un abrazo,</p>
<p style="margin:0;font-family:'Brush Script MT',cursive;font-size:30px;color:#142D4E;">Martha Lucía Hoyos C.</p>
<p style="margin:2px 0 0;font-size:12.5px;letter-spacing:.08em;text-transform:uppercase;color:#b48a3e;font-weight:bold;">Empresaria y líder en mercadeo en red</p></td></tr>
</table>
<p style="max-width:600px;margin:14px auto 0;font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#8a97a8;line-height:1.5;">Recibiste este correo porque realizaste el test «¿Tu multinivel te impulsa o te limita?» y autorizaste el tratamiento de tus datos.</p>
</td></tr></table></body></html>`;

return [{ json: {
  valid: true,
  id, nombre, email, ...answers, puntaje,
  resultado: res.title,
  whatsapp_autoriza: autoriza ? 'Sí' : 'No',
  whatsapp,
  fecha: DateTime.now().setZone('America/Bogota').toFormat('yyyy-MM-dd HH:mm:ss'),
  origen: clean(body.origen, 200),
  asunto: 'Tu resultado del test: ¿Tu multinivel te impulsa o te limita?',
  html
} }];
